return {
s("alg/ee_mod_inv.hpp",{t({"int ee_mod_inv(int a, int m) { return (ee(a, m)[0] % m + m) % m; }"})}),
s("alg/ee.hpp",{t({"array<int, 3> ee(int a, int b) {","  int x = 1, y = 0, z = 0, w = 1;","  while (b) {","    int q = a / b;","    x -= q * z, swap(x, z);","    y -= q * w, swap(y, w);","    a -= q * b, swap(a, b);","  }","  return {x, y, a};","}"})}),
s("alg/linear_sieve.hpp",{t({"vi primes;","vc<bool> is_prime(MAXN + 1, true);","rep(i, 2, MAXN + 1) {","  if (is_prime[i]) {","    primes.pb(i);","  }","  for (auto e : primes) {","    if (i * e > MAXN) break;","    is_prime[i * e] = false;","    if (i % e == 0) {","      break;","    }","  }","}"})}),
s("alg/mod_inv.hpp",{t({"int mod_inv(int a, int m = MOD) { return mod_pow(a, m - 2); }"})}),
s("alg/mod_log.hpp",{t({"// general discrete log","int mod_log(int a, int b, int m) {","  if (b % m == 1 % m) return 0;","  int n = sqrt(m) + 1, e = 1, f, j = 1, i = 2;","  unordered_map<int, int> A;","  while (j <= n && (e = f = e * a % m) != b % m) A[e * b % m] = j++;","  if (e == b % m) return j;","  if (gcd(m, e) == gcd(m, b))","    for (; i <= n + 2; ++i)","      if (A.count(e = e * f % m)) return n * i - A[e];","  return -1;","}"})}),
s("alg/mod_pow.hpp",{t({"int mod_pow(int a, int b, int m = MOD) {","  int rv = 1;","  for (a %= m; b; b >>= 1, (a *= a) %= m)","    if (b & 1) (rv *= a) %= m;","  return rv;","}"})}),
s("combo/binom.hpp",{t({"auto binom = [&](int n, int k) -> int {","  if (n < 0 or n - k < 0 or k < 0) return 0;","  return fact[n] * inv_fact[n - k] % MOD * inv_fact[k] % MOD;","};"})}),
s("combo/fact.hpp",{t({"vi fact(MAXN + 1);","fact[0] = 1;","rep(i, 1, MAXN + 1) fact[i] = fact[i - 1] * i % MOD;"})}),
s("combo/inv_fact.hpp",{t({"vi inv_fact(MAXN + 1);","rep(i, 0, MAXN + 1) inv_fact[i] = mod_inv(fact[i]);"})}),
s("conv/FFT.hpp",{t({"typedef complex<double> C;","typedef vc<double> vd;","void fft(vc<C> &a) {","  int n = sz(a), L = 31 - __builtin_clz(n);","  static vc<complex<long double>> R(2, 1);","  static vc<C> rt(2, 1);","  for (static int k = 2; k < n; k *= 2) {","    R.resize(n);","    rt.resize(n);","    auto x = polar(1.0L, acos(-1.0L) / k);","    rep(i, k, 2 * k) rt[i] = R[i] = i & 1 ? R[i / 2] * x : R[i / 2];","  }","  vi rev(n);","  rep(i, 0, n) rev[i] = (rev[i / 2] | (i & 1) << L) / 2;","  rep(i, 0, n) if (i < rev[i]) swap(a[i], a[rev[i]]);","  for (int k = 1; k < n; k *= 2)","    for (int i = 0; i < n; i += 2 * k) rep(j, 0, k) {","        auto x = (double *) &rt[j + k], y = (double *) &a[i + j + k];","        C z(x[0] * y[0] - x[1] * y[1], x[0] * y[1] + x[1] * y[0]);","        a[i + j + k] = a[i + j] - z;","        a[i + j] += z;","      }","}","vd conv(const vd &a, const vd &b) {","  if (a.empty() || b.empty()) return {};","  vd res(sz(a) + sz(b) - 1);","  int L = 32 - __builtin_clz(sz(res)), n = 1 << L;","  vc<C> in(n), out(n);","  copy(all(a), begin(in));","  rep(i, 0, sz(b)) in[i].imag(b[i]);","  fft(in);","  for (C &x : in) x *= x;","  rep(i, 0, n) out[i] = in[-i & (n - 1)] - conj(in[i]);","  fft(out);","  rep(i, 0, sz(res)) res[i] = imag(out[i]) / (4 * n);","  return res;","}","vi conv(const vi &a, const vi &b) {","  vd c = conv({all(a)}, {all(b)});","  vi rv(sz(c));","  rep(i, 0, sz(c)) rv[i] = llround(c[i]);","  return rv;","}"})}),
s("conv/NTT.hpp",{t({"void ntt(vi &a) {","  int n = sz(a), L = 31 - __builtin_clz(n);","  static vi rt(2, 1);","  for (static int k = 2, s = 2; k < n; k *= 2, s++) {","    rt.resize(n);","    int z[] = {1, mod_pow(62, MOD >> s)};","    rep(i, k, 2 * k) rt[i] = rt[i / 2] * z[i & 1] % MOD;","  }","  vi rev(n);","  rep(i, 0, n) rev[i] = (rev[i / 2] | (i & 1) << L) / 2;","  rep(i, 0, n) if (i < rev[i]) swap(a[i], a[rev[i]]);","  for (int k = 1; k < n; k *= 2)","    for (int i = 0; i < n; i += 2 * k) rep(j, 0, k) {","        int z = rt[j + k] * a[i + j + k] % MOD, &ai = a[i + j];","        a[i + j + k] = ai - z + (z > ai ? MOD : 0);","        ai += (ai + z >= MOD ? z - MOD : z);","      }","}","vi conv(const vi &a, const vi &b) {","  if (a.empty() || b.empty()) return {};","  int s = sz(a) + sz(b) - 1, B = 32 - __builtin_clz(s), n = 1 << B;","  int inv = mod_pow(n, MOD - 2);","  vi L(a), R(b), out(n);","  L.resize(n), R.resize(n);","  ntt(L), ntt(R);","  rep(i, 0, n) out[-i & (n - 1)] = L[i] * R[i] % MOD * inv % MOD;","  ntt(out);","  return {out.begin(), out.begin() + s};","}"})}),
s("dp/sos.hpp",{t({"rep(i, 0, N) rep(j, 0, 1 << N) if (~i >> j & 1) dp[i | 1 << j] += dp[i];"})}),
s("dp/sss1.hpp",{t({"map<int, int> occ;","for (auto e : w) occ[e]++;","bitset<1000000> b;","b[0] = 1;","for (auto [x, n] : occ) {","  b |= b << x, n--;","  if (n % 2) b |= b << x, n--;","  if (n) occ[2 * x] += n / 2;","}"})}),
s("ds/cover_query.hpp",{t({"// https://jilljenn.github.io/tryalgo/_modules/tryalgo/union_rectangles.html#union_rectangles","template <class S, class T>","struct cover_query {"," private:","  struct seg {","    T c;","    S s, w;","  };","","  int n;","  std::vector<seg> data;",""," public:","  cover_query() {}","  cover_query(const std::vector<S> &l)","      : n(1 << std::__lg(2 * l.size() - 1)), data(2 * n, {0, 0, 0}) {","    for (int i = 0; i < l.size(); i++) {","      data[n + i].w = l[i];","    }","    for (int i = n - 1; i > 0; i--) {","      data[i].w = data[i << 1].w + data[i << 1 | 1].w;","    }","  }","  cover_query(int _n) : cover_query(std::vector<S>(_n, 1)) {}","","  S cover() { return data[1].s; }","","  void add(int l, int r, T dc) {","    auto dfs = [&](auto self, int i, int sl, int sr) -> void {","      if (sr <= l or r <= sl) return;","      if (l <= sl and sr <= r) {","        data[i].c += dc;","      } else {","        int sm = sl + (sr - sl) / 2;","        self(self, i << 1, sl, sm);","        self(self, i << 1 | 1, sm, sr);","      }","      if (data[i].c == 0) {","        if (i >= n) {","          data[i].s = 0;","        } else {","          data[i].s = data[i << 1].s + data[i << 1 | 1].s;","        }","      } else {","        data[i].s = data[i].w;","      }","    };","    dfs(dfs, 1, 0, n);","  }","};"})}),
s("ds/dsu_with_potentials.hpp",{t({"template <class S, auto op, auto inv>","struct dsu_with_potentials {","  static_assert(std::is_convertible_v<decltype(op), std::function<S(S, S)>>,","                \"op must work as S(S, S)\");","  static_assert(std::is_convertible_v<decltype(inv), std::function<S(S)>>,","                \"inv must work as S(S)\");",""," private:","  std::vector<int> root;","  std::vector<S> V;",""," public:","  dsu_with_potentials() {}","  dsu_with_potentials(int n, S zero) : root(n, -1), V(n, zero) {}","","  int leader(int a) {","    if (root[a] < 0) return a;","    int p = leader(root[a]);","    V[a] = op(V[a], V[root[a]]);","    return root[a] = p;","  }","","  bool merge(int a, int b, S v) {","    int a2 = leader(a), b2 = leader(b);","    if (a2 == b2) return op(V[b], inv(V[a])) == v;","    if (root[a2] > root[b2]) {","      std::swap(a2, b2);","      std::swap(a, b);","      v = inv(v);","    }","    root[a2] += root[b2];","    root[b2] = a2;","    V[b2] = op(op(v, V[a]), inv(V[b]));","    return true;","  }","","  bool same(int a, int b) { return leader(a) == leader(b); }","","  int size(int a) { return -root[leader(a)]; }","","  S potential(int a) {","    leader(a);","    return V[a];","  }","","  S voltage(int a, int b) { return op(potential(b), inv(potential(a))); }","};"})}),
s("ds/dsu.hpp",{t({"struct dsu {","  vi d;","  dsu(int n) : d(n, -1) {}","  int leader(int a) { return d[a] < 0 ? a : d[a] = leader(d[a]); }","  bool merge(int a, int b) {","    a = leader(a), b = leader(b);","    if (a == b) return 0;","    if (d[a] > d[b]) swap(a, b);","    d[a] += d[b], d[b] = a;","    return 1;","  }","  int size(int a) { return -d[a]; }","};"})}),
s("ds/fenwick_tree.hpp",{t({"struct fenwick_tree {","  int n;","  vi d;","  fenwick_tree(int _n) : n(_n + 1), d(n, 0) {}","  void add(int i, int x) {","    for (i++; i < n; i += i & -i) d[i] += x;","  }","  int sum(int i) {","    int rv = 0;","    for (; i; i -= i & -i) rv += d[i];","    return rv;","  }","  int lower_bound(int x) {","    if (x <= 0) return -1;","    int i = 0;","    for (int j = 1 << __lg(n); j; j >>= 1)","      if (i + j < n and d[i + j] < x) i += j, x -= d[i];","    return i;","  }","};"})}),
s("ds/implicit_treap.hpp",{t({"// TODO: replace size with a general property generic","template <class T>","struct implicit_treap {"," private:","  static std::mt19937 rng;","","  struct node {","    T v;","    node *l, *r;","    int size;","","    node(T _v) : v(_v), l(nullptr), r(nullptr), size(0) {}","  };","","  node *root;","","  static int safe_size(node *a) { return a == nullptr ? 0 : a->size; }","","  static void safe_free(node *a) {","    if (a == nullptr) return;","    safe_free(a->l);","    safe_free(a->r);","    free(a);","  }","","  static void safe_pull(node *a) {","    if (a == nullptr) return;","    a->size = safe_size(a->l) + 1 + safe_size(a->r);","  }","","  static node *build(const std::vector<T> &v) {","    auto dfs = [&](auto self, int l, int r) -> node * {","      if (l == r) return nullptr;","      int m = l + (r - l) / 2;","      node *a = new node(v[m]);","      a->l = self(self, l, m);","      a->r = self(self, m + 1, r);","      safe_pull(a);","      return a;","    };","    return dfs(dfs, 0, v.size());","  }","","  static node *merge(node *l, node *r) {","    if (l == nullptr) return r;","    if (r == nullptr) return l;","    if (rng() % (safe_size(l) + safe_size(r)) < safe_size(l)) {","      l->r = merge(l->r, r);","      safe_pull(l);","      return l;","    } else {","      r->l = merge(l, r->l);","      safe_pull(r);","      return r;","    }","  }","","  static std::pair<node *, node *> split(node *a, int i) {","    if (a == nullptr) return {nullptr, nullptr};","    if (i <= safe_size(a->l)) {","      auto [l, r] = split(a->l, i);","      a->l = r;","      safe_pull(a);","      return {l, a};","    } else {","      auto [l, r] = split(a->r, i - (safe_size(a->l) + 1));","      a->r = l;","      safe_pull(a);","      return {a, r};","    }","  }","","  node *get_node(int i) {","    assert(0 <= i and i < size());","    auto dfs = [&](auto self, node *a, int i) -> node * {","      if (i == safe_size(a->l)) {","        return a;","      } else if (i < safe_size(a->l)) {","        return self(self, a->l, i);","      } else {","        return self(self, a->r, i - (1 + safe_size(a->l)));","      }","    };","    return dfs(dfs, root, i);","  };",""," public:","  implicit_treap() : root(nullptr) {}","","  implicit_treap(const std::vector<T> &v) : root(build(v)) {}","","  implicit_treap(int n, T v) : implicit_treap(std::vector<T>(n, v)) {}","","  ~implicit_treap() { safe_free(root); }","","  int size() const { return safe_size(root); }","","  void insert(int i, T v) {","    assert(0 <= i and i <= size());","    auto [l, r] = split(root, i);","    root = merge(merge(l, new node(v)), r);","  }","","  void erase(int i) {","    assert(0 <= i and i < size());","    auto [l1, r1] = split(root, i);","    auto [l2, r2] = split(r1, 1);","    safe_free(l2);","    root = merge(l1, r2);","  }","","  void set(int i, T v) { get_node(i)->v = v; }","","  T get(int i) { return get_node(i)->v; }","};","template <class T>","std::mt19937 implicit_treap<T>::rng(time(nullptr));"})}),
s("ds/lazy_segtree.hpp",{t({"template <class S, auto op, auto e, class F, auto mp, auto cp, auto id>","struct lazy_segtree {","  int lgn, n;","  vc<S> s;","  vc<F> f;","  lazy_segtree(const vc<S> &v)","      : lgn(__lg(2 * sz(v) - 1)), n(1 << lgn), s(2 * n), f(2 * n, id()) {","    rep(i, 0, sz(v)) s[n + i] = v[i];","    for (int i = n - 1; i > 0; i--) s[i] = op(s[i << 1], s[i << 1 | 1]);","  }","  lazy_segtree(int m) : lazy_segtree(vc(m, e())) {}","  void ch(int i, F g) {","    s[i] = mp(g, s[i]);","    if (i < n) f[i] = cp(f[i], g);","  }","  void push(int i) {","    for (int j = lgn; j > 0; j--) {","      int k = (i + n) >> j;","      ch(k << 1, f[k]);","      ch(k << 1 | 1, f[k]);","      f[k] = id();","    }","  }","  void pull(int i) {","    for (i += n; i >>= 1;) s[i] = mp(f[i], op(s[i << 1], s[i << 1 | 1]));","  }","  S get(int i) {","    push(i);","    return s[n + i];","  }","  void set(int i, S t) {","    push(i);","    s[n + i] = t;","    pull(i);","  }","  void apply(int l, int r, F g) {","    if (l >= r) return;","    int i = l, j = r - 1;","    push(i), push(j);","    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {","      if (l & 1) ch(l++, g);","      if (r & 1) ch(--r, g);","    }","    pull(i), pull(j);","  }","  S prod(int l, int r) {","    if (l >= r) return e();","    push(l), push(r - 1);","    S lv = e(), rv = e();","    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {","      if (l & 1) lv = op(lv, s[l++]);","      if (r & 1) rv = op(s[--r], rv);","    }","    return op(lv, rv);","  }","};"})}),
s("ds/line_container.hpp",{t({"","struct Line {","  mutable ll k, m, p;","  bool operator<(const Line &o) const { return k < o.k; }","  bool operator<(ll x) const { return p < x; }","};","","struct LineContainer : multiset<Line, less<>> {","  // (for doubles, use inf = 1/.0, div(a,b) = a/b)","  static const ll inf = LLONG_MAX;","  ll div(ll a, ll b) {  // floored division","    return a / b - ((a ^ b) < 0 && a % b);","  }","  bool isect(iterator x, iterator y) {","    if (y == end()) return x->p = inf, 0;","    if (x->k == y->k)","      x->p = x->m > y->m ? inf : -inf;","    else","      x->p = div(y->m - x->m, x->k - y->k);","    return x->p >= y->p;","  }","  void add(ll k, ll m) {","    auto z = insert({k, m, 0}), y = z++, x = y;","    while (isect(y, z)) z = erase(z);","    if (x != begin() && isect(--x, y)) isect(x, y = erase(y));","    while ((y = x) != begin() && (--x)->p >= y->p) isect(x, erase(y));","  }","  ll query(ll x) {","    assert(!empty());","    auto l = *lower_bound(x);","    return l.k * x + l.m;","  }","};"})}),
s("ds/ordered_map.hpp",{t({"#include <bits/extc++.h>","","using namespace __gnu_pbds;","","template <class S, class T, class U = less<T>>","using ordered_map =","    tree<S, T, U, rb_tree_tag, tree_order_statistics_node_update>;"})}),
s("ds/ordered_set.hpp",{t({"#include <bits/extc++.h>","","using namespace __gnu_pbds;","","template <class S, class T = less<S>>","using ordered_set =","    tree<S, null_type, T, rb_tree_tag, tree_order_statistics_node_update>;"})}),
s("ds/persistent_segtree.hpp",{t({"// https://usaco.guide/adv/persistent#persistent-segment-tree","// https://github.com/atcoder/ac-library/blob/master/atcoder/segtree.hpp","template <class S, auto op, auto e>","struct persistent_segtree {","  static_assert(std::is_convertible_v<decltype(op), std::function<S(S, S)>>,","                \"op must work as S(S, S)\");","  static_assert(std::is_convertible_v<decltype(e), std::function<S()>>,","                \"e must work as S()\");",""," private:","  struct node {","    S v;","    node *l, *r;","","    node(S _v) : v(_v), l(nullptr), r(nullptr) {}","    node(node *_l, node *_r) : v(e()), l(_l), r(_r) {","      if (l != nullptr) {","        v = op(v, l->v);","      }","      if (r != nullptr) {","        v = op(v, r->v);","      }","    }","  };","","  int n;","  node *root;","","  persistent_segtree(int _n, node *_root) : n(_n), root(_root) {}",""," public:","  persistent_segtree() {}","  persistent_segtree(const std::vector<S> &v) : n(v.size()) {","    auto dfs = [&](auto self, int l, int r) -> node * {","      if (r - l == 1) return new node(v[l]);","","      int m = l + (r - l) / 2;","      return new node(self(self, l, m), self(self, m, r));","    };","    root = dfs(dfs, 0, n);","  }","  persistent_segtree(int _n) : persistent_segtree(std::vector<S>(_n, e())) {}","","  persistent_segtree<S, op, e> set(int i, S v) {","    auto dfs = [&](auto self, node *a, int l, int r) -> node * {","      if (r - l == 1) return new node(v);","","      int m = l + (r - l) / 2;","      if (i < m) {","        return new node(self(self, a->l, l, m), a->r);","      } else {","        return new node(a->l, self(self, a->r, m, r));","      }","    };","    return {n, dfs(dfs, root, 0, n)};","  }","","  S get(int i) const {","    node *a = root;","    int l = 0, r = n;","    while (r - l > 1) {","      int m = l + (r - l) / 2;","      if (i < m) {","        a = a->l;","        r = m;","      } else {","        a = a->r;","        l = m;","      }","    }","    return a->v;","  }","","  S prod(int l, int r) const {","    auto dfs = [&](auto self, node *a, int l2, int r2) -> S {","      if (r <= l2 or r2 <= l) return e();","      if (l <= l2 and r2 <= r) return a->v;","","      int m = l2 + (r2 - l2) / 2;","      return op(self(self, a->l, l2, m), self(self, a->r, m, r2));","    };","    return dfs(dfs, root, 0, n);","  }","","  S all_prod() const { return root->v; }","","  template <bool (*f)(S)>","  int max_right(int l) const {","    return max_right(l, [](S x) { return f(x); });","  }","","  template <class F>","  int max_right(int l, F f) const {","    S v = e();","    auto dfs = [&](auto self, node *a, int l2, int r2) -> int {","      if (r2 <= l) return r2;","      if (l <= l2 and f(op(v, a->v))) {","        v = op(v, a->v);","        return r2;","      }","      if (r2 - l2 == 1) return l2;","","      int m = l2 + (r2 - l2) / 2, r = self(self, a->l, l2, m);","      if (r != m) return r;","      return self(self, a->r, m, r2);","    };","    return dfs(dfs, root, 0, n);","  }","","  template <bool (*f)(S)>","  int min_left(int r) const {","    return min_left(r, [](S x) { return f(x); });","  }","","  template <class F>","  int min_left(int r, F f) const {","    S v = e();","    auto dfs = [&](auto self, node *a, int l2, int r2) -> int {","      if (r <= l2) return l2;","      if (r2 <= r and f(op(a->v, v))) {","        v = op(a->v, v);","        return l2;","      }","      if (r2 - l2 == 1) return r2;","","      int m = l2 + (r2 - l2) / 2, l = self(self, a->r, m, r2);","      if (l != m) return l;","      return self(self, a->l, l2, m);","    };","    return dfs(dfs, root, 0, n);","  }","};"})}),
s("ds/persistent_vector.hpp",{t({"// https://usaco.guide/adv/persistent#path-copying","// Persistent array with insertion and deletion","template <class T>","struct persistent_vector {"," private:","  struct node {","    T v;","    node *l, *r;","","    node() : v(), l(nullptr), r(nullptr) {}","    node(T _v) : v(_v), l(nullptr), r(nullptr) {}","    node(T _v, node *_l, node *_r) : v(_v), l(_l), r(_r) {}","  };","","  int n;","  node *root;","","  persistent_vector(int _n, node *_root) : n(_n), root(_root) {}","","  static int middle(int l, int r) {","    return l + (1 << std::__lg(r - l + 1)) - 1;","  }",""," public:","  persistent_vector() : n(0), root(nullptr) {}","","  persistent_vector(const std::vector<T> &v) : n(v.size()) {","    auto dfs = [&](auto self, int l, int r) -> node * {","      if (l > r) return nullptr;","","      int m = middle(l, r);","      return new node(v[m], self(self, l, m - 1), self(self, m + 1, r));","    };","    root = dfs(dfs, 0, n - 1);","  }","  persistent_vector(int _n, T nil = T())","      : persistent_vector(std::vector<T>(_n, nil)) {}","","  int size() const { return n; }","  bool empty() const { return n == 0; }","","  persistent_vector<T> set(int i, T v) {","    auto dfs = [&](auto self, node *a, int l, int r) -> node * {","      int m = middle(l, r);","      if (m == i) return new node(v, a->l, a->r);","","      if (i < m) {","        return new node(a->v, self(self, a->l, l, m - 1), a->r);","      } else {","        return new node(a->v, a->l, self(self, a->r, m + 1, r));","      }","    };","    return {n, dfs(dfs, root, 0, n - 1)};","  }","","  T get(int i) const {","    node *a = root;","    int l = 0, r = n - 1;","    while (true) {","      int m = middle(l, r);","      if (m == i) return a->v;","","      if (i < m) {","        a = a->l;","        r = m - 1;","      } else {","        a = a->r;","        l = m + 1;","      }","    }","  }","","  // O(\\log(N))","  persistent_vector<T> push_back(T v) {","    auto dfs = [&](auto self, node *a, int l, int r) -> node * {","      if (l > r) return new node(v);","","      int m = middle(l, r);","      if (m - l == r - m) return new node(v, a, nullptr);","","      return new node(a->v, a->l, self(self, a->r, m + 1, r));","    };","    return {n + 1, dfs(dfs, root, 0, n - 1)};","  }","","  // O(\\log(N))","  persistent_vector<T> pop_back() {","    auto dfs = [&](auto self, node *a, int l, int r) -> node * {","      int m = middle(l, r);","      if (m == r) return a->l;","","      return new node(a->v, a->l, self(self, a->r, m + 1, r));","    };","    return {n - 1, dfs(dfs, root, 0, n - 1)};","  }","","  // O(\\log(N+K))","  persistent_vector<T> insert(int i, T v) {","    auto dfs = [&](auto self, node *a, int l, int r, bool check) -> node * {","      if (check) {","        if (l > r) return new node(v);","      } else {","        if (l > r) return nullptr;","        if (r < i) return a;","      }","","      int m = middle(l, r);","      bool push = false;","      if (check) {","        push = m - l == r - m;","        check = push == false;","      }","","      node *a2 = new node(a->v);","      a2->l = self(self, a->l, l, m - 1, false);","      if (m >= i) {","        a2->v = v;","        v = a->v;","      }","      a2->r = self(self, a->r, m + 1, r, check);","","      if (push) {","        return new node(v, a2, nullptr);","      } else {","        return a2;","      }","    };","    return {n + 1, dfs(dfs, root, 0, n - 1, true)};","  }","","  // O(\\log(N+K))","  persistent_vector<T> erase(int i) {","    T v;","    auto dfs = [&](auto self, node *a, int l, int r) -> node * {","      if (l > r) return nullptr;","      if (r < i) return a;","","      int m = middle(l, r);","      if (m == n - 1) {","        v = a->v;","        return self(self, a->l, l, m - 1);","      }","","      node *a2 = new node(a->v);","      a2->r = self(self, a->r, m + 1, r);","      if (m >= i) {","        a2->v = v;","        v = a->v;","      }","      a2->l = self(self, a->l, l, m - 1);","      return a2;","    };","    return {n - 1, dfs(dfs, root, 0, n - 1)};","  }","};"})}),
s("ds/range_add_fenwick_tree.hpp",{t({"// https://usaco.guide/plat/RURQ#implementation","// Fenwick tree with range updates","template <class T>","struct range_add_fenwick_tree {"," private:","  using T2 = double_width_t<T>;","","  int n;","  std::vector<T> m;","  std::vector<T2> b;",""," public:","  range_add_fenwick_tree() {}","  range_add_fenwick_tree(int _n) : n(_n), m(n + 1, 0), b(n + 1, 0) {}","","  void add(int l, int r, T v) {","    assert(0 <= l and l <= r and r <= n);","    for (int i = l + 1; i <= n; i += i & -i) {","      m[i] += v;","      b[i] += (T2) v * l;","    }","    for (int i = r + 1; i <= n; i += i & -i) {","      m[i] -= v;","      b[i] -= (T2) v * r;","    }","  }","","  T sum(int l, int r) {","    assert(0 <= l and l <= r and r <= n);","    T2 rv = 0;","    for (int i = l; i > 0; i -= i & -i) {","      rv -= (T2) m[i] * l - b[i];","    }","    for (int i = r; i > 0; i -= i & -i) {","      rv += (T2) m[i] * r - b[i];","    }","    return rv;","  }","};"})}),
s("ds/rollback_dsu.hpp",{t({"struct rollback_dsu {","  vi d, s;","  vc<tuple<int, int, int>> h;","  rollback_dsu(int n) : d(n, -1) {}","  int leader(int a) { return d[a] < 0 ? a : leader(d[a]); }","  bool merge(int a, int b) {","    a = leader(a), b = leader(b);","    if (a == b) return 0;","    if (d[a] > d[b]) swap(a, b);","    h.eb(a, b, d[b]);","    d[a] += d[b], d[b] = a;","    return 1;","  }","  int size(int a) { return -d[a]; }","  void save() { s.pb(sz(h)); }","  void rollback() {","    while (sz(h) > s.back()) {","      auto [a, b, x] = h.back();","      h.pop_back();","      d[b] = x, d[a] -= d[b];","    }","    s.pop_back();","  }","};"})}),
s("ds/segtree.hpp",{t({"template <class S, auto op, auto e>","struct segtree {","  int n;","  vc<S> s;","  segtree(const vc<S> &v) : n(sz(v)), s(2 * n) {","    rep(i, 0, n) s[n + i] = v[i];","    for (int i = n - 1; i > 0; i--) s[i] = op(s[i << 1], s[i << 1 | 1]);","  }","  segtree(int m) : segtree(vc(m, e())) {}","  S get(int i) { return s[n + i]; }","  void set(int i, S t) {","    for (s[i += n] = t; i >>= 1;) s[i] = op(s[i << 1], s[i << 1 | 1]);","  }","  S prod(int l, int r) {","    S lv = e(), rv = e();","    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {","      if (l & 1) lv = op(lv, s[l++]);","      if (r & 1) rv = op(s[--r], rv);","    }","    return op(lv, rv);","  }","};"})}),
s("ds/sparse_table.hpp",{t({"template <class S, auto op, auto e>","struct sparse_table {","  int n;","  vc<vc<S>> d;","  sparse_table(const vc<S> &v) : n(sz(v)), d(__lg(n) + 1, vc<S>(n, e())) {","    copy(all(v), d[0].begin());","    rep(i, 1, sz(d)) rep(j, 0, n - (1 << i) + 1) d[i][j] =","        op(d[i - 1][j], d[i - 1][j + (1 << (i - 1))]);","  }","  S prod(int l, int r) {","    if (l >= r) return e();","    int i = __lg(r - l);","    return op(d[i][l], d[i][r - (1 << i)]);","  }","};"})}),
s("ds/trie.hpp",{t({"struct trie {","  struct node {","    int ch[2]{};","  };","  vc<node> d;","  trie() : d(1) {}","  int ensure(int &a) { return a ?: (a = sz(d), d.eb(), sz(d) - 1); }","  void add(int x) {","    for (int i = 60, a = 0; i--;) {","      a = ensure(d[a].ch[x >> i & 1]);","    }","  }","  int get(int ps) {","    int a = 0;","    for (int i = 60; i--;) {","      if (!(a = d[a].ch[ps >> i & 1])) return -1;","    }","    return a;","  }","};"})}),
s("ds/xor_basis.hpp",{t({"template <class T>","struct xor_basis {"," private:","  int n, m;","  std::vector<T> basis;",""," public:","  xor_basis(int _n) : n(_n), m(0), basis(n, 0) {}","  xor_basis() : xor_basis(8 * sizeof(T)) {}","","  bool insert(T x) {","    for (int i = n - 1; i >= 0; i--) {","      if (~x >> i & 1) continue;","      if (basis[i] == 0) {","        for (int j = 0; j < i; j++) {","          if (~x >> j & 1) continue;","          x ^= basis[j];","        }","        basis[i] = x;","        m++;","        for (int j = i + 1; j < n; j++) {","          if (~basis[j] >> i & 1) continue;","          basis[j] ^= x;","        }","        return true;","      }","      x ^= basis[i];","    }","    return false;","  }","","  T size() { return m; }","","  bool contains(T x) {","    for (int i = 0; i < n; i++) {","      if (~x >> i & 1) continue;","      if (basis[i] == 0) return false;","      x ^= basis[i];","    }","    return true;","  }","","  T order_of_key(T x) {","    int x2 = 0, j = m - 1, rv = 0;","    for (int i = n - 1; i >= 0; i--) {","      if (basis[i] == 0) continue;","      if ((x2 ^ basis[i]) <= x) {","        rv += 1 << j;","        x2 ^= basis[i];","      }","      j--;","    }","    return rv;","  }","","  T find_by_order(T k) {","    int k2 = 0, j = m - 1, rv = 0;","    for (int i = n - 1; i >= 0; i--) {","      if (basis[i] == 0) continue;","      if (k2 + (1 << j) <= k) {","        rv ^= basis[i];","        k2 += 1 << j;","      }","      j--;","    }","    return rv;","  }","};"})}),
s("graph/find_bridges.hpp",{t({"// https://cp-algorithms.com/graph/bridge-searching.html","std::vector<std::pair<int, int>> find_bridges(","    const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  std::vector<bool> seen(n, false);","  std::vector<int> tin(n), tmin(n);","  std::vector<std::pair<int, int>> rv;","  int t = 0;","  auto dfs = [&](auto self, int a, int p) -> void {","    seen[a] = true;","    tin[a] = tmin[a] = t++;","    bool skipped = false;","    for (auto b : adj[a]) {","      if (b == p and !skipped) {","        skipped = true;","        continue;","      }","      if (seen[b]) {","        tmin[a] = std::min(tmin[a], tin[b]);","      } else {","        self(self, b, a);","        tmin[a] = std::min(tmin[a], tmin[b]);","        if (tmin[b] > tin[a]) {","          int u = a, v = b;","          if (u > v) {","            std::swap(u, v);","          }","          rv.push_back({u, v});","        }","      }","    }","  };","  for (int i = 0; i < n; i++) {","    if (seen[i]) continue;","    dfs(dfs, 0, -1);","  }","  return rv;","}"})}),
s("graph/is_acyclic.hpp",{t({"bool is_acyclic(const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  auto order = toposort(adj);","  std::vector<bool> seen(n, false);","  for (auto a : order) {","    seen[a] = true;","    for (auto b : adj[a]) {","      if (seen[b]) return false;","    }","  }","  return true;","}"})}),
s("graph/mbm_graph.hpp",{t({"// https://judge.yosupo.jp/submission/339108","struct mbm_graph {"," private:","  int n, m;","  std::vector<std::vector<int>> adj;","  std::vector<int> mate;",""," public:","  mbm_graph(int _n, int _m) : n(_n), m(_m), adj(n + m), mate(n + m, -1) {}","","  void add_edge(int l, int r) {","    adj[l].push_back(n + r);","    adj[n + r].push_back(l);","  }","","  int match() {","    std::queue<int> q1;","    for (int i = n; i < n + m; i++) {","      q1.push(i);","    }","    while (true) {","      std::vector<int> depth(n + m, std::numeric_limits<int>::max());","      std::queue<int> q2;","      for (int i = 0; i < n; i++) {","        if (mate[i] != -1) continue;","        depth[i] = 0;","        q2.push(i);","      }","      while (q2.size() > 0) {","        int a = q2.front();","        q2.pop();","","        for (auto b : adj[a]) {","          if (depth[a] + 1 >= depth[b]) continue;","          depth[b] = depth[a] + 1;","","          int c = mate[b];","          if (c != -1) {","            depth[c] = depth[b] + 1;","            q2.push(c);","          }","        }","      }","","      for (int i = 0; i < n + m; i++) {","        if (q1.empty()) {","          return (n + m - count(mate.begin(), mate.end(), -1)) / 2;","        }","","        int a = q1.front();","        q1.pop();","","        int d = std::numeric_limits<int>::max(), b;","        for (auto c : adj[a]) {","          if (depth[c] >= d) continue;","          d = depth[c];","          b = c;","        }","        if (d < std::numeric_limits<int>::max()) {","          depth[a] = depth[b] + 1;","","          int c = mate[b];","          if (c != -1) {","            mate[c] = -1;","            q1.push(c);","          }","","          mate[a] = b;","          mate[b] = a;","          depth[b] += 2;","        }","      }","    }","  }","","  std::vector<std::pair<int, int>> matching() {","    std::vector<std::pair<int, int>> rv;","    for (int i = 0; i < n; i++) {","      if (mate[i] == -1) continue;","      rv.push_back({i, mate[i] - n});","    }","    return rv;","  }","","  std::vector<std::vector<int>> minimum_chain_cover() {","    assert(n == m);","    std::vector<std::vector<int>> rv;","    for (int i = 0; i < n; i++) {","      if (mate[n + i] != -1) continue;","","      std::vector<int> chain;","      int a = i;","      while (a >= 0) {","        chain.push_back(a);","        a = mate[a] - n;","      }","      rv.push_back(chain);","    }","    return rv;","  }","};"})}),
s("graph/mcf_graph.hpp",{t({"namespace atcoder {","","template <class Cap, class Cost>","struct mcf_graph {"," public:","  mcf_graph() {}","  explicit mcf_graph(int n) : _n(n) {}","","  int add_edge(int from, int to, Cap cap, Cost cost) {","    assert(0 <= from && from < _n);","    assert(0 <= to && to < _n);","    assert(0 <= cap);","    assert(0 <= cost);","    int m = int(_edges.size());","    _edges.push_back({from, to, cap, 0, cost});","    return m;","  }","","  struct edge {","    int from, to;","    Cap cap, flow;","    Cost cost;","  };","","  edge get_edge(int i) {","    int m = int(_edges.size());","    assert(0 <= i && i < m);","    return _edges[i];","  }","  std::vector<edge> edges() { return _edges; }","","  std::pair<Cap, Cost> flow(int s, int t) {","    return flow(s, t, std::numeric_limits<Cap>::max());","  }","  std::pair<Cap, Cost> flow(int s, int t, Cap flow_limit) {","    return slope(s, t, flow_limit).back();","  }","  std::vector<std::pair<Cap, Cost>> slope(int s, int t) {","    return slope(s, t, std::numeric_limits<Cap>::max());","  }","  std::vector<std::pair<Cap, Cost>> slope(int s, int t, Cap flow_limit) {","    assert(0 <= s && s < _n);","    assert(0 <= t && t < _n);","    assert(s != t);","","    int m = int(_edges.size());","    std::vector<int> edge_idx(m);","","    auto g = [&]() {","      std::vector<int> degree(_n), redge_idx(m);","      std::vector<std::pair<int, _edge>> elist;","      elist.reserve(2 * m);","      for (int i = 0; i < m; i++) {","        auto e = _edges[i];","        edge_idx[i] = degree[e.from]++;","        redge_idx[i] = degree[e.to]++;","        elist.push_back({e.from, {e.to, -1, e.cap - e.flow, e.cost}});","        elist.push_back({e.to, {e.from, -1, e.flow, -e.cost}});","      }","      auto _g = internal::csr<_edge>(_n, elist);","      for (int i = 0; i < m; i++) {","        auto e = _edges[i];","        edge_idx[i] += _g.start[e.from];","        redge_idx[i] += _g.start[e.to];","        _g.elist[edge_idx[i]].rev = redge_idx[i];","        _g.elist[redge_idx[i]].rev = edge_idx[i];","      }","      return _g;","    }();","","    auto result = slope(g, s, t, flow_limit);","","    for (int i = 0; i < m; i++) {","      auto e = g.elist[edge_idx[i]];","      _edges[i].flow = _edges[i].cap - e.cap;","    }","","    return result;","  }",""," private:","  int _n;","  std::vector<edge> _edges;","","  // inside edge","  struct _edge {","    int to, rev;","    Cap cap;","    Cost cost;","  };","","  std::vector<std::pair<Cap, Cost>> slope(internal::csr<_edge> &g, int s, int t,","                                          Cap flow_limit) {","    // variants (C = maxcost):","    // -(n-1)C <= dual[s] <= dual[i] <= dual[t] = 0","    // reduced cost (= e.cost + dual[e.from] - dual[e.to]) >= 0 for all edge","","    // dual_dist[i] = (dual[i], dist[i])","    std::vector<std::pair<Cost, Cost>> dual_dist(_n);","    std::vector<int> prev_e(_n);","    std::vector<bool> vis(_n);","    struct Q {","      Cost key;","      int to;","      bool operator<(Q r) const { return key > r.key; }","    };","    std::vector<int> que_min;","    std::vector<Q> que;","    auto dual_ref = [&]() {","      for (int i = 0; i < _n; i++) {","        dual_dist[i].second = std::numeric_limits<Cost>::max();","      }","      std::fill(vis.begin(), vis.end(), false);","      que_min.clear();","      que.clear();","","      // que[0..heap_r) was heapified","      size_t heap_r = 0;","","      dual_dist[s].second = 0;","      que_min.push_back(s);","      while (!que_min.empty() || !que.empty()) {","        int v;","        if (!que_min.empty()) {","          v = que_min.back();","          que_min.pop_back();","        } else {","          while (heap_r < que.size()) {","            heap_r++;","            std::push_heap(que.begin(), que.begin() + heap_r);","          }","          v = que.front().to;","          std::pop_heap(que.begin(), que.end());","          que.pop_back();","          heap_r--;","        }","        if (vis[v]) continue;","        vis[v] = true;","        if (v == t) break;","        // dist[v] = shortest(s, v) + dual[s] - dual[v]","        // dist[v] >= 0 (all reduced cost are positive)","        // dist[v] <= (n-1)C","        Cost dual_v = dual_dist[v].first, dist_v = dual_dist[v].second;","        for (int i = g.start[v]; i < g.start[v + 1]; i++) {","          auto e = g.elist[i];","          if (!e.cap) continue;","          // |-dual[e.to] + dual[v]| <= (n-1)C","          // cost <= C - -(n-1)C + 0 = nC","          Cost cost = e.cost - dual_dist[e.to].first + dual_v;","          if (dual_dist[e.to].second - dist_v > cost) {","            Cost dist_to = dist_v + cost;","            dual_dist[e.to].second = dist_to;","            prev_e[e.to] = e.rev;","            if (dist_to == dist_v) {","              que_min.push_back(e.to);","            } else {","              que.push_back(Q{dist_to, e.to});","            }","          }","        }","      }","      if (!vis[t]) {","        return false;","      }","","      for (int v = 0; v < _n; v++) {","        if (!vis[v]) continue;","        // dual[v] = dual[v] - dist[t] + dist[v]","        //         = dual[v] - (shortest(s, t) + dual[s] - dual[t]) +","        //         (shortest(s, v) + dual[s] - dual[v]) = - shortest(s,","        //         t) + dual[t] + shortest(s, v) = shortest(s, v) -","        //         shortest(s, t) >= 0 - (n-1)C","        dual_dist[v].first -= dual_dist[t].second - dual_dist[v].second;","      }","      return true;","    };","    Cap flow = 0;","    Cost cost = 0, prev_cost_per_flow = -1;","    std::vector<std::pair<Cap, Cost>> result = {{Cap(0), Cost(0)}};","    while (flow < flow_limit) {","      if (!dual_ref()) break;","      Cap c = flow_limit - flow;","      for (int v = t; v != s; v = g.elist[prev_e[v]].to) {","        c = std::min(c, g.elist[g.elist[prev_e[v]].rev].cap);","      }","      for (int v = t; v != s; v = g.elist[prev_e[v]].to) {","        auto &e = g.elist[prev_e[v]];","        e.cap += c;","        g.elist[e.rev].cap -= c;","      }","      Cost d = -dual_dist[s].first;","      flow += c;","      cost += c * d;","      if (prev_cost_per_flow == d) {","        result.pop_back();","      }","      result.push_back({flow, cost});","      prev_cost_per_flow = d;","    }","    return result;","  }","};","","}  // namespace atcoder"})}),
s("graph/mf_graph.hpp",{t({"namespace atcoder {","","template <class Cap>","struct mf_graph {"," public:","  mf_graph() : _n(0) {}","  explicit mf_graph(int n) : _n(n), g(n) {}","","  int add_edge(int from, int to, Cap cap) {","    assert(0 <= from && from < _n);","    assert(0 <= to && to < _n);","    assert(0 <= cap);","    int m = int(pos.size());","    pos.push_back({from, int(g[from].size())});","    int from_id = int(g[from].size());","    int to_id = int(g[to].size());","    if (from == to) to_id++;","    g[from].push_back(_edge{to, to_id, cap});","    g[to].push_back(_edge{from, from_id, 0});","    return m;","  }","","  struct edge {","    int from, to;","    Cap cap, flow;","  };","","  edge get_edge(int i) {","    int m = int(pos.size());","    assert(0 <= i && i < m);","    auto _e = g[pos[i].first][pos[i].second];","    auto _re = g[_e.to][_e.rev];","    return edge{pos[i].first, _e.to, _e.cap + _re.cap, _re.cap};","  }","  std::vector<edge> edges() {","    int m = int(pos.size());","    std::vector<edge> result;","    for (int i = 0; i < m; i++) {","      result.push_back(get_edge(i));","    }","    return result;","  }","  void change_edge(int i, Cap new_cap, Cap new_flow) {","    int m = int(pos.size());","    assert(0 <= i && i < m);","    assert(0 <= new_flow && new_flow <= new_cap);","    auto &_e = g[pos[i].first][pos[i].second];","    auto &_re = g[_e.to][_e.rev];","    _e.cap = new_cap - new_flow;","    _re.cap = new_flow;","  }","","  Cap flow(int s, int t) { return flow(s, t, std::numeric_limits<Cap>::max()); }","  Cap flow(int s, int t, Cap flow_limit) {","    assert(0 <= s && s < _n);","    assert(0 <= t && t < _n);","    assert(s != t);","","    std::vector<int> level(_n), iter(_n);","    internal::simple_queue<int> que;","","    auto bfs = [&]() {","      std::fill(level.begin(), level.end(), -1);","      level[s] = 0;","      que.clear();","      que.push(s);","      while (!que.empty()) {","        int v = que.front();","        que.pop();","        for (auto e : g[v]) {","          if (e.cap == 0 || level[e.to] >= 0) continue;","          level[e.to] = level[v] + 1;","          if (e.to == t) return;","          que.push(e.to);","        }","      }","    };","    auto dfs = [&](auto self, int v, Cap up) {","      if (v == s) return up;","      Cap res = 0;","      int level_v = level[v];","      for (int &i = iter[v]; i < int(g[v].size()); i++) {","        _edge &e = g[v][i];","        if (level_v <= level[e.to] || g[e.to][e.rev].cap == 0) continue;","        Cap d = self(self, e.to, std::min(up - res, g[e.to][e.rev].cap));","        if (d <= 0) continue;","        g[v][i].cap += d;","        g[e.to][e.rev].cap -= d;","        res += d;","        if (res == up) return res;","      }","      level[v] = _n;","      return res;","    };","","    Cap flow = 0;","    while (flow < flow_limit) {","      bfs();","      if (level[t] == -1) break;","      std::fill(iter.begin(), iter.end(), 0);","      Cap f = dfs(dfs, t, flow_limit - flow);","      if (!f) break;","      flow += f;","    }","    return flow;","  }","","  std::vector<bool> min_cut(int s) {","    std::vector<bool> visited(_n);","    internal::simple_queue<int> que;","    que.push(s);","    while (!que.empty()) {","      int p = que.front();","      que.pop();","      visited[p] = true;","      for (auto e : g[p]) {","        if (e.cap && !visited[e.to]) {","          visited[e.to] = true;","          que.push(e.to);","        }","      }","    }","    return visited;","  }",""," private:","  int _n;","  struct _edge {","    int to, rev;","    Cap cap;","  };","  std::vector<std::pair<int, int>> pos;","  std::vector<std::vector<_edge>> g;","};","","}  // namespace atcoder"})}),
s("graph/scc_graph.hpp",{t({"namespace atcoder {","","struct scc_graph {"," public:","  scc_graph() : internal(0) {}","  explicit scc_graph(int n) : internal(n) {}","","  void add_edge(int from, int to) {","    int n = internal.num_vertices();","    assert(0 <= from && from < n);","    assert(0 <= to && to < n);","    internal.add_edge(from, to);","  }","","  std::vector<std::vector<int>> scc() { return internal.scc(); }",""," private:","  internal::scc_graph internal;","};","","}  // namespace atcoder"})}),
s("graph/toposort_with_cmp.hpp",{t({"std::vector<int> toposort(const std::vector<std::vector<int>> &adj,","                          const std::function<bool(int, int)> &cmp) {","  int n = adj.size();","","  std::vector<int> degree(n, 0);","  for (auto adja : adj) {","    for (auto b : adja) {","      degree[b]++;","    }","  }","","  auto rcmp = [&](int a, int b) -> bool { return cmp(b, a); };","  std::priority_queue<int, std::vector<int>, decltype(rcmp)> pq(rcmp);","  auto nudge = [&](int a) -> void {","    if (degree[a] != 0) return;","    pq.push(a);","  };","  for (int i = 0; i < n; i++) {","    nudge(i);","  }","  std::vector<int> rv;","  while (pq.size() > 0) {","    int a = pq.top();","    pq.pop();","    rv.push_back(a);","    for (auto b : adj[a]) {","      if (degree[b] == 0) continue;","      degree[b]--;","      nudge(b);","    }","  }","  return rv;","}"})}),
s("graph/toposort.hpp",{t({"std::vector<int> toposort(const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  std::vector<bool> seen(n, false);","  std::vector<int> rv;","  auto dfs = [&](auto self, int a) -> void {","    if (seen[a]) return;","    seen[a] = true;","","    for (auto b : adj[a]) {","      self(self, b);","    }","    rv.push_back(a);","  };","  for (int i = 0; i < n; i++) {","    dfs(dfs, i);","  }","  reverse(rv.begin(), rv.end());","  return rv;","}"})}),
s("graph/two_sat.hpp",{t({"namespace atcoder {","","// Reference:","// B. Aspvall, M. Plass, and R. Tarjan,","// A Linear-Time Algorithm for Testing the Truth of Certain Quantified Boolean","// Formulas","struct two_sat {"," public:","  two_sat() : _n(0), scc(0) {}","  explicit two_sat(int n) : _n(n), _answer(n), scc(2 * n) {}","","  void add_clause(int i, bool f, int j, bool g) {","    assert(0 <= i && i < _n);","    assert(0 <= j && j < _n);","    scc.add_edge(2 * i + (f ? 0 : 1), 2 * j + (g ? 1 : 0));","    scc.add_edge(2 * j + (g ? 0 : 1), 2 * i + (f ? 1 : 0));","  }","  bool satisfiable() {","    auto id = scc.scc_ids().second;","    for (int i = 0; i < _n; i++) {","      if (id[2 * i] == id[2 * i + 1]) return false;","      _answer[i] = id[2 * i] < id[2 * i + 1];","    }","    return true;","  }","  std::vector<bool> answer() { return _answer; }",""," private:","  int _n;","  std::vector<bool> _answer;","  internal::scc_graph scc;","};","","}  // namespace atcoder"})}),
s("heuristic/rng/frng.hpp",{t({"inline double frng() { return (rng() >> 11) * (1. / (1ll << 53)); }"})}),
s("heuristic/rng/rng.hpp",{t({"inline uint64_t rng() {","  static uint64_t x = 88172645463325252ULL;","  x ^= x >> 12;","  x ^= x << 25;","  x ^= x >> 27;","  return x * 0x2545F4914F6CDD1DULL;","}","","inline uint32_t rng(uint32_t n) { return ((rng() >> 32) * n) >> 32; }"})}),
s("heuristic/sa.hpp",{t({"","template <class S>","S sa(S state, double T0, double T1, double tl = 1.95) {","  using namespace chrono;","  auto t0 = steady_clock::now();","  double T;","  int score = state.score(), best_score = score;","  S best_state = state;","  for (int i = 0;; i++) {","    if ((i & 255) == 0) {","      double w = duration<double>(steady_clock::now() - t0).count() / tl;","      if (w >= 1.0) break;","      T = T0 * pow(T1 / T0, w);","    }","    auto move = state.gen();","    int delta = state.eval(move);","    if (delta <= 0 || (T > 1e-9 && frng() < exp(-delta / T))) {","      state.apply(move);","      score += delta;","      if (score < best_score) {","        best_score = score;","        best_state = state;","      }","    }","  }","  return best_state;","}"})}),
s("mat/matinv.hpp",{t({"bool matinv(auto &a) {","  int n = sz(a);","  rep(i, 0, n) a[i].resize(2 * n), a[i][n + i] = 1;","  if (rref(a, n) < n) return 0;","  rep(i, 0, n) a[i].erase(begin(a[i]), begin(a[i]) + n);","  return 1;","}"})}),
s("mat/matmul.hpp",{t({"vc<vi> matmul(vc<vi> a, vc<vi> b) {","  vc rv(sz(a), vi(sz(b[0]), 0));","  rep(i, 0, sz(a)) rep(j, 0, sz(b[0])) rep(k, 0, sz(a[0])) {","    rv[i][j] += a[i][k] * b[k][j];","  }","  return rv;","}"})}),
s("mat/matpow.hpp",{t({"vc<vi> matpow(vc<vi> x, int y) {","  vc rv(sz(x), vi(sz(x), 0));","  rep(i, 0, sz(x)) rv[i][i] = 1;","  for (; y; y >>= 1, x = matmul(x, x))","    if (y & 1) rv = matmul(rv, x);","  return rv;","}"})}),
s("mat/rref.hpp",{t({"int rref(auto &a, int vars) {","  int n = sz(a), m = sz(a[0]), r = 0;","  rep(c, 0, vars) if (r < n) {","    int p = r;","    rep(i, r, n) if (abs(a[i][c]) > abs(a[p][c])) p = i;","    if (abs(a[p][c]) < 1e-9) continue;","    swap(a[p], a[r]);","    for (int j = m; j-- > c;) a[r][j] /= a[r][c];","    rep(i, 0, n) if (i != r) for (int j = m; j-- > c;) a[i][j] -=","        a[i][c] * a[r][j];","    r++;","  }","  return r;","}"})}),
s("misc/pratt_parser.hpp",{t({"// TODO: write pratt parser","//","// the way i understand it is that there's 3 main functions:","//","// 1. parse operand","// 2. parse operator","// 3. get binding power","//","// parsing operands is for parsing stuff that can't really be divided by an","// operator, so stuff like numbers, symbols, unary operators (negation, etc.),","// or parentheses","//","// parsing operators takes an lhs operand and an operator and calls a function","// to parse the rhs operand and then combines them as necessary","//","// binding power decides when to stop parsing for a subexpression. if an","// operator's binding power is too small, that means we can't use the operator","// just yet; we need to handle the higher binding power operators first. so i","// guess in simple terms, binding power is just \"what should i do first?\". i","// think left/right associativity comes into play when dealing with two binding","// powers that are equal","//","// i think we can implement this nicely with a stack? or cleaner with recursion?","//","// i think operand and operator parsing are forced to have access to the parsing","// context to handle stuff with trailing tokens like parentheses or functions","//","// honestly though, i feel like trailing tokens aren't that big a deal because","// they don't provide any new information. i believe we can make these a no-op,","// at least for what a pratt parser is supposed to provide"})}),
s("string/SuffixArray.hpp",{t({"struct SuffixArray {","  vi sa, lcp;","  SuffixArray(string &s, int lim = 256) {  // or basic_string<int>","    int n = sz(s) + 1, k = 0, a, b;","    vi x(all(s)), y(n), ws(max(n, lim));","    x.pb(0), sa = lcp = y, iota(all(sa), 0);","    for (int j = 0, p = 0; p < n; j = max(1ll, j * 2), lim = p) {","      p = j, iota(all(y), n - j);","      rep(i, 0, n) if (sa[i] >= j) y[p++] = sa[i] - j;","      fill(all(ws), 0);","      rep(i, 0, n) ws[x[i]]++;","      rep(i, 1, lim) ws[i] += ws[i - 1];","      for (int i = n; i--;) sa[--ws[x[y[i]]]] = y[i];","      swap(x, y), p = 1, x[sa[0]] = 0;","      rep(i, 1, n) a = sa[i - 1], b = sa[i],","                   x[b] = (y[a] == y[b] && y[a + j] == y[b + j]) ? p - 1 : p++;","    }","    for (int i = 0, j; i < n - 1; lcp[x[i++]] = k)","      for (k &&k--, j = sa[x[i] - 1]; s[i + k] == s[j + k]; k++);","  }","};"})}),
s("string/z_algorithm.hpp",{t({"namespace atcoder {","","// Reference:","// D. Gusfield,","// Algorithms on Strings, Trees, and Sequences: Computer Science and","// Computational Biology","template <class T>","std::vector<int> z_algorithm(const std::vector<T> &s) {","  int n = int(s.size());","  if (n == 0) return {};","  std::vector<int> z(n);","  z[0] = 0;","  for (int i = 1, j = 0; i < n; i++) {","    int &k = z[i];","    k = (j + z[j] <= i) ? 0 : std::min(j + z[j] - i, z[i - j]);","    while (i + k < n && s[k] == s[i + k]) k++;","    if (j + z[j] < i + z[i]) j = i;","  }","  z[0] = n;","  return z;","}","","std::vector<int> z_algorithm(const std::string &s) {","  int n = int(s.size());","  std::vector<int> s2(n);","  for (int i = 0; i < n; i++) {","    s2[i] = s[i];","  }","  return z_algorithm(s2);","}","","}  // namespace atcoder"})}),
s("tree/cartesian_tree.hpp",{t({"// vc<int> v -> vc<T> v","// v[i] > v[st.back()] -> above(v[i], v[st.back()])","pair<int, vc<pii>> cartesian_tree(vc<int> v) {","  vc<pii> rv(sz(v), {-1, -1});","  vi st;","  rep(i, 0, sz(v)) {","    while (sz(st) and v[i] > v[st.back()]) {","      rv[i].fs = st.back();","      st.pop_back();","    }","    if (sz(st)) rv[st.back()].sd = i;","    st.pb(i);","  }","  return {st[0], rv};","}"})}),
s("tree/centroid_decomp.hpp",{t({"vc<bool> cut(N, false);","vi size(N);","auto dfs1 = [&](auto self, int a, int p) -> int {","  size[a] = 1;","  for (auto b : adj[a]) {","    if (b == p or cut[b]) continue;","    size[a] += self(self, b, a);","  }","  return size[a];","};","","auto dfs2 = [&](auto self, int a, int p, int n) -> int {","  for (auto b : adj[a]) {","    if (b == p or cut[b]) continue;","    if (size[b] * 2 > n) return self(self, b, a, n);","  }","  return a;","};","","auto dfs3 = [&](auto self, int a) -> void {","  a = dfs2(dfs2, a, -1, dfs1(dfs1, a, -1));","  cut[a] = true;","  for (auto b : adj[a]) {","    if (cut[b]) continue;","    self(self, b);","  }","};"})}),
s("tree/find_centroids.hpp",{t({"// Returns all (one or two) centroids of the tree","// O(N)","std::vector<int> find_centroids(const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  std::vector<int> size(n);","  auto dfs_size = [&](auto self, int a, int p) -> int {","    size[a] = 1;","    for (auto b : adj[a]) {","      if (b == p) continue;","      size[a] += self(self, b, a);","    }","    return size[a];","  };","  dfs_size(dfs_size, 0, -1);","","  std::vector<int> rv;","  auto dfs_find = [&](auto self, int a, int p) -> void {","    for (auto b : adj[a]) {","      if (b == p) continue;","      if (size[b] * 2 > n) {","        return self(self, b, a);","      } else if (size[b] * 2 == n) {","        rv.push_back(b);","      }","    }","    rv.push_back(a);","  };","  dfs_find(dfs_find, 0, -1);","  return rv;","}"})}),
s("tree/prufer_code.hpp",{t({"// https://cp-algorithms.com/graph/pruefer_code.html","// Returns the Prüfer code of a labelled tree","std::vector<int> prufer_code(const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  std::vector<int> parent(n, -1);","  auto dfs = [&](auto self, int a) -> void {","    for (auto b : adj[a]) {","      if (b == parent[a]) continue;","      self(self, b);","    }","  };","  dfs(dfs, n - 1);","","  std::vector<int> degree(n, 0);","  for (int i = 0; i < n; i++) {","    degree[i] = adj[i].size();","  }","","  int j = -1;","  for (int i = 0; i < n; i++) {","    if (degree[i] != 1) continue;","    j = i;","    break;","  }","","  std::vector<int> rv;","  int a = j;","  for (int i = 0; i < n - 2; i++) {","    int p = parent[a];","    rv.push_back(p);","","    degree[p]--;","    if (degree[p] == 1 and p < j) {","      a = p;","    } else {","      do {","        j++;","      } while (degree[j] != 1);","      a = j;","    }","  }","  return rv;","}"})}),
s("tree/rrdp.hpp",{t({"template <typename S, typename T>","vc<S> rrdp(const vc<vi> &adj, T nil,","           auto trans,    // (dp, a, i) -> tdp","           auto merge,    // (tdp, tdp) -> tdp","           auto finalize  // (tdp, a) -> dp",") {","  int n = sz(adj);","","  vi order(n);","  vc<pii> par(n);","  auto dfs = [&](auto self, int a, int p) -> void {","    order.pb(a);","    rep(i, 0, sz(adj[a])) {","      int b = adj[a][i];","      if (b == p) {","        par[a] = {p, i};","        continue;","      }","      self(self, b, a);","    }","  };","  dfs(dfs, 0, -1);","","  vc<S> dp(n);","  vc<T> ddp(n);","  vc<vc<T>> tdp(n);","  reverse(all(order));","  for (auto a : order) {","    tdp[a].resize(sz(adj[a]));","    ddp[a] = nil;","    rep(i, 0, sz(adj[a])) {","      int b = adj[a][i];","      if (b == par[a].fs) continue;","      tdp[a][i] = trans(dp[b], a, i);","      ddp[a] = merge(ddp[a], tdp[a][i]);","    }","    dp[a] = finalize(ddp[a], a);","  }","","  vc<T> pdp(n, nil), sdp(n, nil);","  reverse(all(order));","  for (auto a : order) {","    rep(i, 0, sz(adj[a]) - 1) { pdp[i + 1] = merge(pdp[i], tdp[a][i]); }","    sdp[sz(adj[a]) - 1] = nil;","    for (int i = sz(adj[a]) - 1; i >= 1; --i) {","      sdp[i - 1] = merge(tdp[a][i], sdp[i]);","    }","    rep(i, 0, sz(adj[a])) {","      int b = adj[a][i];","      if (b == par[a].fs) continue;","      int j = par[b].sd;","      tdp[b][j] = trans(finalize(merge(pdp[i], sdp[i]), a), b, j);","      dp[b] = finalize(merge(ddp[b], tdp[b][j]), b);","    }","  }","  return dp;","}"})}),
s("tree/sack.hpp",{t({"void sack(const std::function<void(int)> &insert,","          const std::function<void()> &clear,","          const std::function<void(int)> &callback,","          const std::vector<std::vector<int>> &adj, int r = 0) {","  int n = adj.size();","","  std::vector<int> order(n);","  int t = 0;","  auto dfs = [&](auto self, int a, int p) -> void {","    order[t] = a;","    t++;","","    int l = t;","    for (int i = 1; i < (int) adj[a].size(); i++) {","      if (adj[a][i] == p) continue;","      self(self, adj[a][i], a);","      clear();","    }","    int r = t;","","    if ((int) adj[a].size() > 0 and adj[a][0] != p) {","      self(self, adj[a][0], a);","      for (int i = l; i < r; i++) {","        insert(order[i]);","      }","    }","    insert(a);","","    callback(a);","  };","  dfs(dfs, r, -1);","}"})}),
s("tree/sort_hld.hpp",{t({"void sort_hld(std::vector<std::vector<int>> &adj, int r = 0) {","  auto dfs = [&](auto self, int a, int p) -> int {","    int rv = 1, nmax = 0;","    for (int i = 0; i < (int) adj[a].size(); i++) {","      if (adj[a][i] == p) {","        std::swap(adj[a][i], adj[a].back());","      }","","      if (adj[a][i] == p) continue;","      int n = self(self, adj[a][i], a);","      rv += n;","","      if (i == 0) {","        nmax = n;","      } else {","        if (n > nmax) {","          std::swap(adj[a][0], adj[a][i]);","          nmax = n;","        }","      }","    }","    return rv;","  };","  dfs(dfs, r, -1);","}"})}),
s("tree/tree_hash_rooted.hpp",{t({"// https://rng-58.blogspot.com/2017/02/hashing-and-probability-of-collision.html","// Returns a hash of the unlabeled rooted tree","// O(N)","template <long long MOD = (1ll << 61) - 1>","long long tree_hash(const std::vector<std::vector<int>> &adj, int r) {","  int n = adj.size();","","  std::vector<int> depth(n);","  auto dfs_depth = [&](auto self, int a, int p) -> void {","    depth[a] = 0;","    for (auto b : adj[a]) {","      if (b == p) continue;","      self(self, b, a);","      depth[a] = std::max(depth[a], depth[b] + 1);","    }","  };","  dfs_depth(dfs_depth, r, -1);","","  static std::mt19937_64 rng(time(nullptr));","  static std::vector<long long> vars = {1};","  while ((int) vars.size() < depth[r] + 1) {","    vars.push_back(rng() % MOD);","  }","","  auto dfs_hash = [&](auto self, int a, int p) -> long long {","    long long hash = 1;","    for (auto b : adj[a]) {","      if (b == p) continue;","      hash = (__int128) hash * (vars[depth[a]] + self(self, b, a)) % MOD;","    }","    return hash;","  };","  return dfs_hash(dfs_hash, r, -1);","}"})}),
s("tree/tree_hash_unrooted.hpp",{t({"// Returns a hash of the unlabeled unrooted tree","// O(N)","template <long long MOD = (1ll << 61) - 1>","long long tree_hash(const std::vector<std::vector<int>> &adj) {","  int n = adj.size();","","  auto roots = find_centroids(adj);","  std::vector<long long> hashes;","  for (auto r : roots) {","    hashes.push_back(tree_hash<long long, MOD>(adj, r));","  }","  sort(hashes.begin(), hashes.end());","","  static long long base = std::mt19937_64(time(nullptr))() % MOD;","  long long rv = 0;","  for (auto e : hashes) {","    rv = ((__int128) rv * base + e) % MOD;","  }","  return rv;","}"})}),
s("tree/tree_utils.hpp",{t({"// Euler tour and binary lifting-based tree utils","// TODO:","// - O(1) RMQ LCA (or see https://codeforces.com/blog/entry/153134)","// - O(1) kth ancestor (ladder)","// - Built-in HLD","struct tree_utils {"," private:","  const std::vector<std::vector<int>> &adj;","  int n, logn;","  int r;","  std::vector<int> in, out;","  std::vector<int> depth;","  std::vector<std::vector<int>> anc;",""," public:","  tree_utils(const std::vector<std::vector<int>> &_adj, int _r = 0)","      : adj(_adj),","        n(adj.size()),","        logn(std::__lg(n) + 1),","        r(_r),","        in(n),","        out(n),","        depth(n),","        anc(n, std::vector<int>(logn)) {","    int t = 0;","    auto dfs = [&](auto self, int a, int p, int d) -> void {","      in[a] = t++;","      anc[a][0] = p;","      depth[a] = d;","      for (auto b : adj[a]) {","        if (b == p) continue;","        self(self, b, a, d + 1);","      }","      out[a] = t;","    };","    dfs(dfs, r, r, 0);","","    for (int i = 1; i < logn; i++) {","      for (int j = 0; j < n; j++) {","        anc[j][i] = anc[anc[j][i - 1]][i - 1];","      }","    }","  }","","  int get_index(int a) const { return in[a]; }","  std::pair<int, int> get_range(int a) const { return {in[a], out[a]}; }","","  int get_depth(int a) const { return depth[a]; }","","  int get_parent(int a) const {","    assert(a != r);","    return anc[a][0];","  }","","  bool is_anc(int a, int b) const {","    return in[a] <= in[b] and out[a] >= out[b];","  }","","  int lca(int a, int b) const {","    if (is_anc(a, b)) return a;","    if (is_anc(b, a)) return b;","","    for (int i = logn - 1; i >= 0; i--) {","      if (!is_anc(anc[a][i], b)) {","        a = anc[a][i];","      }","    }","    return anc[a][0];","  }","","  int dist(int a, int b) const {","    return depth[a] + depth[b] - 2 * depth[lca(a, b)];","  }","","  int kth_anc(int a, int k) const {","    assert(0 <= k and k <= depth[a]);","    for (int i = logn - 1; i >= 0; i--) {","      if (k >> i & 1) {","        a = anc[a][i];","      }","    }","    return a;","  }","","  int kth_on_path(int a, int b, int k) const {","    assert(0 <= k and k <= dist(a, b));","    int c = lca(a, b);","    if (k <= dist(a, c)) {","      return kth_anc(a, k);","    } else {","      return kth_anc(b, dist(a, b) - k);","    }","  }","","  bool is_on_path(int a, int b, int c) const {","    return is_anc(lca(a, b), c) and (is_anc(c, a) or is_anc(c, b));","  }","","  bool is_in_subtree(int a, int b, int r) const { return is_on_path(r, b, a); }","  bool is_in_subtree(int a, int b) const { return is_in_subtree(a, b, r); }","","  // https://www.youtube.com/watch?v=czySm7bUHgY","  // Returns the root and edges of a virtual tree containing the given vertices","  // O(V\\log(V))","  std::pair<int, std::vector<std::pair<int, int>>> virtual_tree(","      std::vector<int> v) const {","    int k = v.size();","    assert(k > 0);","","    auto cmp = [&](int a, int b) -> bool { return in[a] < in[b]; };","    sort(v.begin(), v.end(), cmp);","    for (int i = 0; i + 1 < k; i++) {","      v.push_back(lca(v[i], v[i + 1]));","    }","    sort(v.begin(), v.end(), cmp);","    v.erase(unique(v.begin(), v.end()), v.end());","","    std::vector<int> stack;","    std::vector<std::pair<int, int>> rv;","    for (auto a : v) {","      while (stack.size() >= 2 and !is_anc(stack.back(), a)) {","        rv.push_back({stack.end()[-2], stack.back()});","        stack.pop_back();","      }","      stack.push_back(a);","    }","    while (stack.size() >= 2) {","      rv.push_back({stack.end()[-2], stack.back()});","      stack.pop_back();","    }","    return {stack[0], rv};","  }","","  std::vector<int> subtree(int r) {","    std::vector<int> rv;","    auto dfs = [&](auto self, int a, int p) -> void {","      rv.push_back(a);","      for (auto b : adj[a]) {","        if (b == p) continue;","        self(self, b, a);","      }","    };","    dfs(dfs, r, anc[r][0]);","    return rv;","  }","};"})}),
}
